package org.brightstats.stats;
import java.nio.file.*;
import java.util.*;
import com.google.gson.*;
public final class PredictionInferenceChecks {
    static int checks;static void check(boolean value){checks++;if(!value)throw new AssertionError("Predictive inference check "+checks);}
    static void reject(Runnable action){try{action.run();throw new AssertionError("Invalid predictive inference accepted");}catch(IllegalArgumentException expected){checks++;}}
    public static void main(String[] args)throws Exception{Path output=Path.of(args[0]);Files.createDirectories(output);Gson gson=new GsonBuilder().serializeSpecialFloatingPointValues().create();JsonArray cases=new JsonArray();var paired=PredictionInference.paired("KNOWN",-1,-1,PredictionInference.Benchmark.INDICATOR_AVERAGE,new double[]{1,1,1},new double[]{2,3,4},.95);check(paired.meanDifference()==-2);check(Math.abs(paired.standardDeviation()-1)<1e-14);check(Math.abs(paired.statistic()+Math.sqrt(12))<1e-13);check(paired.pOneSided()<.05&&paired.upper()>0&&paired.upperOneSided()<0);var constant=PredictionInference.paired("CONSTANT",-1,-1,PredictionInference.Benchmark.LINEAR_MODEL,new double[]{1,1,1},new double[]{2,2,2},.95);check(constant.status().equals("ZERO_EMPIRICAL_LOSS_VARIANCE")&&Double.isNaN(constant.pOneSided()));reject(()->PredictionInference.paired("INVALID",0,0,PredictionInference.Benchmark.LINEAR_MODEL,new double[]{-1},new double[]{0},.95));
        JsonArray predictions=JsonParser.parseString(Files.readString(Path.of(args[1]))).getAsJsonArray();for(var element:predictions){var point=gson.fromJson(element.getAsJsonObject().get("result"),Prediction.Result.class);var inference=PredictionInference.evaluate(point,.95);for(var comparison:inference.comparisons()){check(comparison.observations()<=point.assignments()[0].length);if(Double.isFinite(comparison.pOneSided())){check(comparison.pHolm()>=comparison.pOneSided()-1e-15);check(comparison.pHolm()<=1);}}JsonObject item=new JsonObject();item.add("prediction",gson.toJsonTree(point));item.add("result",gson.toJsonTree(inference));cases.add(item);}
        var options=new Prediction.Options(Prediction.Scheme.K_FOLD,2,2,.2,42);List<Prediction.Row> rows=new ArrayList<>();double[] actual={0,1,2,3,4},forecast={0,.8,1.9,3.1,3.9};int[][] assignments={{1,1,1,2,2},{2,2,2,1,1}};for(int repeat=0;repeat<2;repeat++)for(int row=0;row<5;row++)rows.add(new Prediction.Row(repeat+1,assignments[repeat][row],row+1,0,actual[row],forecast[row],2,actual[row]));var point=new Prediction.Result(options,"known","none","known",assignments,List.of(new Prediction.Target(1,1,"Y")),rows,List.of(),List.of(),List.of());var inference=PredictionInference.evaluate(point,.95);check(inference.metrics().getFirst().zeroActual()==2);check(inference.metrics().getFirst().percentageObservations()==8);check(inference.comparisons().stream().allMatch(comparison->comparison.observations()==5));check(inference.metrics().getFirst().medianAbsoluteError()>=0);JsonObject item=new JsonObject();item.add("prediction",gson.toJsonTree(point));item.add("result",gson.toJsonTree(inference));cases.add(item);List<Prediction.Row> duplicates=new ArrayList<>(rows);duplicates.add(rows.getFirst());reject(()->PredictionInference.evaluate(new Prediction.Result(options,"invalid","none","known",assignments,point.targets(),duplicates,List.of(),List.of(),List.of()),.95));Thread.currentThread().interrupt();try{PredictionInference.evaluate(point,.95);throw new AssertionError("Predictive inference ignored cancellation");}catch(java.util.concurrent.CancellationException expected){checks++;}finally{Thread.interrupted();}Files.writeString(output.resolve("cases.json"),gson.toJson(cases));System.out.println("{\"cases\":"+cases.size()+",\"checks\":"+checks+"}");}
}
